package logger

import (
	"reflect"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"
)

var protoMessageType = reflect.TypeOf((*proto.Message)(nil)).Elem()

type protoInfo struct {
	walk bool
	// aligned with MessageDescriptor.Fields()
	fields []protoFieldInfo
}

type protoFieldInfo struct {
	sensitive bool
	json      bool
}

// redactProto masks a clone of m and returns the clone. The clone keeps the
// Go type of m and so its own MarshalJSON: messages generated by
// protoc-gen-go-gsv encode with protojson, and rebuilding them as maps would
// turn int64 strings into numbers and break the Elasticsearch mapping.
func (r *Redactor) redactProto(m proto.Message, depth int) (interface{}, bool) {
	pm := m.ProtoReflect()
	if !pm.IsValid() || !r.protoScan(pm, depth+1, false) {
		return nil, false
	}
	c := proto.Clone(m)
	r.protoScan(c.ProtoReflect(), depth+1, true)
	return c, true
}

func (r *Redactor) protoInfoFor(md protoreflect.MessageDescriptor) *protoInfo {
	if v, ok := r.protoTypes.Load(md); ok {
		return v.(*protoInfo)
	}
	fields := md.Fields()
	info := &protoInfo{
		walk:   r.computeProtoNeedsWalk(md, make(map[protoreflect.FullName]bool)),
		fields: make([]protoFieldInfo, fields.Len()),
	}
	for i := range info.fields {
		info.fields[i] = r.classifyProtoField(fields.Get(i))
	}
	v, _ := r.protoTypes.LoadOrStore(md, info)
	return v.(*protoInfo)
}

// classifyProtoField matches both the proto name and the JSON name, since
// encoding/json and protojson output use different ones.
func (r *Redactor) classifyProtoField(fd protoreflect.FieldDescriptor) protoFieldInfo {
	s1, j1 := r.classifyKey(string(fd.Name()))
	s2, j2 := r.classifyKey(fd.JSONName())
	return protoFieldInfo{
		sensitive: s1 || s2,
		json:      (j1 || j2) && fd.Kind() == protoreflect.StringKind,
	}
}

// computeProtoNeedsWalk must only be cached for the root message, see
// computeNeedsWalk.
func (r *Redactor) computeProtoNeedsWalk(md protoreflect.MessageDescriptor, visiting map[protoreflect.FullName]bool) bool {
	if visiting[md.FullName()] {
		return false
	}
	visiting[md.FullName()] = true
	fields := md.Fields()
	for i := 0; i < fields.Len(); i++ {
		fd := fields.Get(i)
		if fi := r.classifyProtoField(fd); fi.sensitive || fi.json {
			return true
		}
		if fd.IsMap() {
			if fd.MapKey().Kind() == protoreflect.StringKind {
				return true
			}
			if vd := fd.MapValue().Message(); vd != nil && r.computeProtoNeedsWalk(vd, visiting) {
				return true
			}
			continue
		}
		if sub := fd.Message(); sub != nil && r.computeProtoNeedsWalk(sub, visiting) {
			return true
		}
	}
	return false
}

// protoScan reports whether pm holds anything to redact. With mutate set it
// also redacts pm in place, so it must only be called that way on a clone.
func (r *Redactor) protoScan(pm protoreflect.Message, depth int, mutate bool) bool {
	if depth > r.maxDepth {
		return false
	}
	md := pm.Descriptor()
	info := r.protoInfoFor(md)
	if !info.walk {
		return false
	}
	fields := md.Fields()
	changed := false
	for i := 0; i < fields.Len(); i++ {
		fd := fields.Get(i)
		if !pm.Has(fd) {
			continue
		}
		fi := info.fields[i]
		var hit bool
		switch {
		case fi.sensitive:
			hit = r.protoMaskField(pm, fd, mutate)
		case fd.IsMap():
			hit = r.protoScanMap(pm, fd, depth, mutate)
		case fd.IsList():
			hit = r.protoScanList(pm, fd, fi.json, depth, mutate)
		case fd.Message() != nil:
			var sub protoreflect.Message
			if mutate {
				sub = pm.Mutable(fd).Message()
			} else {
				sub = pm.Get(fd).Message()
			}
			hit = r.protoScan(sub, depth+1, mutate)
		case fi.json:
			if ns, ok := r.redactJSONText(pm.Get(fd).String()); ok {
				hit = true
				if mutate {
					pm.Set(fd, protoreflect.ValueOfString(ns))
				}
			}
		}
		if hit {
			if !mutate {
				return true
			}
			changed = true
		}
	}
	return changed
}

// protoMaskField hides a populated sensitive field. Strings are masked;
// anything else is cleared, which protojson with EmitUnpopulated still
// writes with the same JSON type (0, false, "", [], {} or null).
func (r *Redactor) protoMaskField(pm protoreflect.Message, fd protoreflect.FieldDescriptor, mutate bool) bool {
	if fd.Kind() == protoreflect.StringKind && !fd.IsMap() {
		if fd.IsList() {
			l := listOf(pm, fd, mutate)
			changed := false
			for i := 0; i < l.Len(); i++ {
				s := l.Get(i).String()
				m := r.mask(s)
				if m == s {
					continue
				}
				if !mutate {
					return true
				}
				changed = true
				l.Set(i, protoreflect.ValueOfString(m))
			}
			return changed
		}
		s := pm.Get(fd).String()
		m := r.mask(s)
		if m == s {
			return false
		}
		if mutate {
			pm.Set(fd, protoreflect.ValueOfString(m))
		}
		return true
	}
	if mutate {
		pm.Clear(fd)
	}
	return true
}

func (r *Redactor) protoScanMap(pm protoreflect.Message, fd protoreflect.FieldDescriptor, depth int, mutate bool) bool {
	strKey := fd.MapKey().Kind() == protoreflect.StringKind
	vfd := fd.MapValue()
	subWalk := vfd.Message() != nil && r.protoInfoFor(vfd.Message()).walk
	if !strKey && !subWalk {
		return false
	}
	if !mutate {
		mp := pm.Get(fd).Map()
		hit := false
		mp.Range(func(k protoreflect.MapKey, v protoreflect.Value) bool {
			if strKey && r.isSensitive(k.String()) {
				hit = vfd.Kind() != protoreflect.StringKind || r.mask(v.String()) != v.String()
			} else if subWalk {
				hit = r.protoScan(v.Message(), depth+1, false)
			}
			return !hit
		})
		return hit
	}
	mp := pm.Mutable(fd).Map()
	// collect first: the map must not be modified while ranging
	var keys []protoreflect.MapKey
	mp.Range(func(k protoreflect.MapKey, _ protoreflect.Value) bool {
		keys = append(keys, k)
		return true
	})
	changed := false
	for _, k := range keys {
		if strKey && r.isSensitive(k.String()) {
			if vfd.Kind() != protoreflect.StringKind {
				mp.Clear(k)
				changed = true
				continue
			}
			s := mp.Get(k).String()
			if m := r.mask(s); m != s {
				mp.Set(k, protoreflect.ValueOfString(m))
				changed = true
			}
		} else if subWalk && r.protoScan(mp.Mutable(k).Message(), depth+1, true) {
			changed = true
		}
	}
	return changed
}

func (r *Redactor) protoScanList(pm protoreflect.Message, fd protoreflect.FieldDescriptor, jsonKey bool, depth int, mutate bool) bool {
	l := listOf(pm, fd, mutate)
	changed := false
	if vd := fd.Message(); vd != nil {
		if !r.protoInfoFor(vd).walk {
			return false
		}
		for i := 0; i < l.Len(); i++ {
			if r.protoScan(l.Get(i).Message(), depth+1, mutate) {
				if !mutate {
					return true
				}
				changed = true
			}
		}
		return changed
	}
	if !jsonKey {
		return false
	}
	for i := 0; i < l.Len(); i++ {
		if ns, ok := r.redactJSONText(l.Get(i).String()); ok {
			if !mutate {
				return true
			}
			changed = true
			l.Set(i, protoreflect.ValueOfString(ns))
		}
	}
	return changed
}

func listOf(pm protoreflect.Message, fd protoreflect.FieldDescriptor, mutate bool) protoreflect.List {
	if mutate {
		return pm.Mutable(fd).List()
	}
	return pm.Get(fd).List()
}

// protoDescriptorOf returns the descriptor of a proto message pointer type,
// or nil when t is not one.
func protoDescriptorOf(t reflect.Type) protoreflect.MessageDescriptor {
	if t.Kind() != reflect.Ptr || !t.Implements(protoMessageType) {
		return nil
	}
	return reflect.Zero(t).Interface().(proto.Message).ProtoReflect().Descriptor()
}
